def create_initial_cycles(apps, schema_editor):
    AjoGroup = apps.get_model("groups", "AjoGroup")
    GroupMembership = apps.get_model("groups", "GroupMembership")
    AjoCycle = apps.get_model("groups", "AjoCycle")
    CycleParticipant = apps.get_model("groups", "CycleParticipant")

    db = schema_editor.connection.alias

    # Translate the old group lifecycle into the new cycle lifecycle.
    status_mapping = {
        "draft": "draft",
        "open": "setup",
        "closed": "setup",
        "ready": "ready",
        "active": "active",
        "completed": "completed",
        "cancelled": "cancelled",
    }

    for group in AjoGroup.objects.using(db).all().iterator():

        cycle_status = status_mapping.get(group.status, "draft")

        # A group that has already started is treated as an existing Ajo.
        onboarding_type = (
            "existing"
            if group.status in ["active", "completed"]
            else "new"
        )

        cycle, created = AjoCycle.objects.using(db).get_or_create(
            group_id=group.pk,
            cycle_number=1,
            defaults={
                "onboarding_type": onboarding_type,
                "contribution_amount": group.contribution_amount,
                "frequency": group.frequency,
                "payout_method": group.payout_method,
                "start_date": group.start_date,
                "status": cycle_status,
            },
        )

        # Only approved group members enter the initial cycle.
        memberships = GroupMembership.objects.using(db).filter(
            group_id=group.pk,
            status="approved",
        )

        for membership in memberships.iterator():
            participant_status = "active"

            CycleParticipant.objects.using(db).get_or_create(
                cycle_id=cycle.pk,
                membership_id=membership.pk,
                defaults={
                    "status": participant_status,
                },
            )


